from django.http import JsonResponse
from django.shortcuts import get_object_or_404
from django.urls import path

from .models import Item


def item_payload(item):
    return {
        "id": item.id,
        "name": item.name,
        "price": str(item.price),
        "category": item.category.name,
    }


def item_list(request):
    items = Item.objects.select_related("category").all()
    return JsonResponse({"items": [item_payload(item) for item in items]})


def item_detail(request, item_id):
    item = get_object_or_404(Item.objects.select_related("category"), pk=item_id)
    return JsonResponse(item_payload(item))


urlpatterns = [
    path("items/", item_list, name="item-list"),
    path("items/<int:item_id>/", item_detail, name="item-detail"),
]
